from pathlib import Path
import hashlib, json
root = Path('products/distribution/sqlite-community-directory')
match = [p for p in root.rglob('*') if p.is_file() and hashlib.sha256(p.read_bytes()).hexdigest() == '17cc9de7d7d8e93b4946fe2f5930181460de70e683d2b837012814dd82a68248']
if not match:
    print(json.dumps({'status': 'CAPTURE_NOT_FOUND_IN_SELECTED_INPUTS'}))
else:
    section = ''
    entries = {}
    contribution = []
    lines = match[0].read_text().splitlines()
    for line in lines:
        if line.startswith('## '):
            section = line[3:].strip()
        if section in ('Misc', 'SQLite Documentation / History') and line.lstrip().startswith(('- ', '* ')):
            entries.setdefault(section, []).append(line)
        if 'pull request' in line.lower() or 'contribut' in line.lower():
            contribution.append(line)
    result = {'source': str(match[0]), 'sections': entries, 'contribution_lines': contribution, 'scope': 'Captured README only. Evaluate neighboring listings and published terms before recommending operator submission.'}
    print(json.dumps(result, ensure_ascii=False))
